var i=`0346-kasespatzle`;var t=`world-0346`;var a=`DE`;var s=`western-europe`;var o=4;var l=46;var r={en:`Käsespätzle`,ua:`Кезешпецле`};var d={en:`A traditional Germany dish made with all-purpose flour, chicken egg, yellow onion, emmental. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Німеччина. Основні інгредієнти: пшеничне борошно універсальне, куряче яйце, жовта цибуля, емменталь. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`all-purpose-flour`,360,`g`],[`chicken-egg`,4,`pcs`],[`water`,120,`ml`],[`table-salt`,5,`g`]]},{en:`Cook the listed ingredients in simmering water for about 8 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 8 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:8,i:[]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 13 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 13 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:13,i:[[`yellow-onion`,210,`g`],[`unsalted-butter`,65,`g`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:8,i:[[`emmental`,330,`g`]]},{en:`Roast in a preheated 190°C oven for about 8 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 8 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:8,i:[]}];var g={slug:i,id:t,country:`DE`,region:s,servings:4,minutes:46,title:r,text:d,steps:u};export{a as country,g as default,t as id,l as minutes,s as region,o as servings,i as slug,u as steps,d as text,r as title};